INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fragmented Fear', 'You take on the role of Miyako, a schoolgirl who awakens in an abandoned school cloaked in an eerie red mist. With no memory of how she got there, she is hunted by a ghostly girl with hollow eyes and cryptic motives. Paired with a haunting soundtrack and a tense, oppressive atmosphere, the game draws you into a nightmare where every corridor conceals dark secrets and every shadow could be your end. Survive, piece together the school’s mysteries, and confront the terror within the mist.' FROM games WHERE igdb_id = 342245 ON CONFLICT (game_id, language_code) DO NOTHING;
