INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninjas Stars', 'Ninja Stars is an action-packed arcade game where players strategically fire and deflect ninja stars to break down surrounding walls. Use physics-based ricochet mechanics and precision aiming to eliminate obstacles and clear the level. With each wall sequence presenting new challenges, it’s a test of both reflexes and strategy as you work to complete each stage!' FROM games WHERE igdb_id = 344967 ON CONFLICT (game_id, language_code) DO NOTHING;
