INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Desafio Quiz', 'Desafio Quiz is a game packed with thousands of challenges for you to have fun and learn. With it, you can create rooms for group battles and stimulate your thinking while learning through play! In Desafio Quiz, you can track your performance statistics, unlock achievements, and have fun while challenging your mind! You can also follow your ranking compared to other players on the global, monthly, and daily leaderboards, and study for exams using a special module with real questions from previous tests.' FROM games WHERE igdb_id = 357376 ON CONFLICT (game_id, language_code) DO NOTHING;
