INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mines', 'Trapped underground after a routine exploration gone wrong, you find yourself sprinting through claustrophobic tunnels. Hot on your heels is an immense, grotesque spider—its scuttling echoes drown out your own panicked breaths. With each step, the shadowy walls seem to close.' FROM games WHERE igdb_id = 357664 ON CONFLICT (game_id, language_code) DO NOTHING;
