INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixel Puzzles Christmas Jigsaws', 'Pixel Puzzles Christmas Jigsaws brings festive relaxation to your screen with 25 beautifully crafted Christmas-themed jigsaw puzzles. Choose your challenge level with puzzles ranging from 96 to 425 pieces. The game is perfect for both casual players and seasoned puzzlers alike. Whether you’re looking to unwind after a long day or get into the Christmas spirit, this traditional jigsaw experience offers calm, fun, and festive cheer.' FROM games WHERE igdb_id = 389397 ON CONFLICT (game_id, language_code) DO NOTHING;
