INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hypnosis Knight-Princess', 'As Gina, your mission is to travel across the kingdom of Triss and break the hypnosis curse affecting her people. To do this, you''ll need to craft magic fragments and dispelling stones, which will help you perform exorcisms on the citizens. Each exorcism consumes time, so plan accordingly! You''ll also face automatic battles with enemies that will take up both time and HP. The more citizens you free, the more regions of the world map you''ll unlock, potentially revealing new dungeons and powerful bosses to defeat.' FROM games WHERE igdb_id = 363664 ON CONFLICT (game_id, language_code) DO NOTHING;
