INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alone: Shattered Tribes', 'An isometric survival RPG without the survival. Collect resources and craft items and weapons. Build a settlement on your island. Hunt in the darkest forests, or slay the undead in the cursed crypts. Explore the islands, unite the shattered tribes, and become a Jarl worthy of the sagas.' FROM games WHERE igdb_id = 368732 ON CONFLICT (game_id, language_code) DO NOTHING;
