INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Einstein''s Cats', 'Cats in boxes; alive or dead? Wait, no, no this isn’t Schroedinger. This is Einstein’s Cats! A cozy, relaxing logic puzzle game about cats and boxes; which cats go where? But be careful, you know how picky cats can be!' FROM games WHERE igdb_id = 291594 ON CONFLICT (game_id, language_code) DO NOTHING;
