INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Remember Saint Patrick', 'Celebrate the special day with Remember St Patrick, a festive card-matching memory game perfect for all ages! Flip cards to reveal delightful St Patrick-themed icons like leprechauns, clovers, and rainbows, while testing your memory across increasing levels of fun and challenge. With cheerful visuals, cozy music, and endless holiday spirit, it’s the perfect way to make your gaming season merry and bright!' FROM games WHERE igdb_id = 335079 ON CONFLICT (game_id, language_code) DO NOTHING;
