INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChessBlaze', 'ChessBlaze is a strategy game based on Chess but with a major twist: TURNS DO NOT EXIST! Who needs turns if you can have energy instead. Every move costs energy, no need to wait for opponents response. Some game-modes feature "PowerTiles". They offer unique abilities for pieces entering them!' FROM games WHERE igdb_id = 337281 ON CONFLICT (game_id, language_code) DO NOTHING;
