INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolf Girlfriend', 'From an average guy to the hero of a legendary prophecy, your fate takes a wild turn after saving an injured wolf. The bite you received seals your destiny, transforming you into a werewolf with the full moon approaching ! Now, with three mysterious wolf girls vying for your attention, you''ll have to navigate this intense love triangle to break the curse and survive !' FROM games WHERE igdb_id = 354259 ON CONFLICT (game_id, language_code) DO NOTHING;
