INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcade Archives 2: Munch Mobile', 'Munch Mobile is an action game released by SNK in 1983. Pilot a mysterious car with arms, picking up fuel and food along the way. The goal is to make it home before your fuel runs out. Place trash left from your food into bins to earn big points! Show consideration in public spaces and enjoy a fun drive!' FROM games WHERE igdb_id = 374668 ON CONFLICT (game_id, language_code) DO NOTHING;
