INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HelmetFire', 'HelmetFire is a rougelite motorcycle multitasking type endless runner that is as relaxing, or as taxing, as you want it to be. Unlock endless score multipliers and compete on the online leaderboard to be the best, or unwind and watch the numbers go up at your own pace' FROM games WHERE igdb_id = 351265 ON CONFLICT (game_id, language_code) DO NOTHING;
