INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Regulus: The Advent', 'Regulus: The Advent is a real time strategy RPG developed in collaboration of a Thai-based game studio, Jumbo Jumps, and TV Tokyo Corporation. It tells a story of cadets from a Demon Realm''s military academy on a mission to save the universe from enigmatic corrupters called the Vespers.' FROM games WHERE igdb_id = 373720 ON CONFLICT (game_id, language_code) DO NOTHING;
