INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Câi & Darren: Code Calamity', 'A charming 2.5D turn-based RPG starring two college professors—Darren, a master of "Swipe" code, and Câi, a wizard of "Brew" language—who team up to descend into the mysterious depths of the MAD program building and confront the unleashed Calamity Virus. Players switch between the duo to reprogram terminals, solve programming puzzles, and battle rogue errors using a deck-based chip combat system that rewards combo strategies. Your goal: debug the virus and stop it from crashing everything before it’s too late.' FROM games WHERE igdb_id = 350385 ON CONFLICT (game_id, language_code) DO NOTHING;
