INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Quest Fantasy', 'Wield enchanted swords, explore ancient castles, and unravel word puzzles charged with mystical power. Each grid hides words that bring you closer to becoming a true hero of the realm. Defeat challenges, unlock secrets, and let your imagination guide you through a storybook world where every word is part of your adventure. Are you ready to prove yourself in the ultimate fantasy word quest?' FROM games WHERE igdb_id = 385067 ON CONFLICT (game_id, language_code) DO NOTHING;
