INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mordeny', 'Prepare for fast-paced, strategic combat in Mordeny, a thrilling 2D top-down shooter where quick reflexes and tactical thinking are your best weapons. Explore unique gamemodes and customize your own character as you unlock new abilities and gear. Whether you''re battling solo or teaming up with friends, Mordeny offers an action-packed adventure like no other where every battle demands precision and skill. Join the fight and experience the thrill today!' FROM games WHERE igdb_id = 356804 ON CONFLICT (game_id, language_code) DO NOTHING;
