INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Rivals', 'Welcome to ANIMAL RIVALS, the most intense monkey shooter on Meta Quest. Inspired by classic shooters and the gorilla movement system, you can challenge friends (or enemies!) to 1v1, 2v2, or 3v3 duels, get chaotic with Team Deathmatch, or defeat a zombie horde in the Infected mode!' FROM games WHERE igdb_id = 370847 ON CONFLICT (game_id, language_code) DO NOTHING;
