INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growmancer', 'A small incremental game about greening the land. Play as the Growmancer, a wizard traveling worlds with his canine companion to transform wastelands into fertile grounds and battle destructive wildfires. Upgrade both via a skill tree. Challenge yourself or just relax.' FROM games WHERE igdb_id = 344723 ON CONFLICT (game_id, language_code) DO NOTHING;
