INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Winds of Valen', 'Winds of Valen is a free-to-play MMORPG that embraces traditional progression mechanics in a fantasy open world. Players develop their characters through skill-based advancement in areas like combat, mining, and smithing, while exploring a seamless environment filled with rare loot and resource gathering opportunities. The game focuses on earned achievements rather than microtransactions, following the design philosophy of classic MMORPGs.' FROM games WHERE igdb_id = 379327 ON CONFLICT (game_id, language_code) DO NOTHING;
