INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Turbo', 'In Road Turbo, the quiet suburban streets turn into your racetrack. You begin alone, a single runner facing a line of barrels, barricades, and enemies. With every step forward the pace quickens, and the challenge grows sharper. Collect boosts, find the right gates, and suddenly one becomes many. Your tiny crew doubles, triples, and surges down the road, transforming into a force powerful enough to crash through whatever stands in the way.' FROM games WHERE igdb_id = 371830 ON CONFLICT (game_id, language_code) DO NOTHING;
