INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leafing Home', 'Leafing Home is a cozy adventure game where you play as a small squirrel on a quest to retrieve the World Tree’s stolen fruit and find your way back home. Explore a vibrant world filled with quirky characters, and help restore nature to its former glory. Master unique flight mechanics, tackle aerial challenges, solve puzzles, and dive into a variety of fun mini-games. This heartwarming tale of belonging and environmentalism is perfect for players of all ages.' FROM games WHERE igdb_id = 333006 ON CONFLICT (game_id, language_code) DO NOTHING;
